using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieve a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app_name"] = "MyService",
            ["version"] = "1.0.0",
            ["environment"] = "production",
            ["max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "Application Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "MyService",
            Version = "1.0.0",
            Environment = "production",
            MaxConnections = 100,
            Features = new { EnableCache = true, EnableMetrics = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://endpoints",
        Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Returns available API endpoint definitions.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/api/users", Method = "GET", Description = "List all users" },
            new { Path = "/api/users/{id}", Method = "GET", Description = "Get user by ID" },
            new { Path = "/api/health", Method = "GET", Description = "Health check" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

